const dataIn = $input.first().json.data;
const dataJson = JSON.parse(dataIn);
const totalBids = dataJson.response.response.numFound;
const totalPages = Math.ceil(totalBids / 10);
const thisPage = $('data holder').first().json.thisPage+1;
const bidIDs = $('data holder').first().json.bidIDs;
const docs = dataJson.response.response.docs;
for (const doc of docs) {
  bidIDs.push(doc.id);
}
const credentials = {
  "type":$('data holder').first().json.credentials.type,
  "csrf":$('data holder').first().json.credentials.csrf,
  "expires":$('data holder').first().json.credentials.expires,
  "setCookies":$('data holder').first().json.credentials.setCookies,
};
return [
  {
    json: {
      totalPages,
      thisPage,
      bidIDs,
      credentials ,
      category:$('data holder').first().json.category
    },
  },
];

