This is a detailed list of mandatory and optional documents required to participate in the provided GeM tender, ensuring full conformity to GeM tender rules.

---

**{
  "should": true,
  "listOfDocumentsRequired": [
    {
      "Document Name": "Company Registration Certificate / Business Proof",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To prove legal existence and registration of the bidding entity.",
      "Reference Section/Page": "Implied by general GeM tender rules for any registered business.",
      "Any prescribed format or annexure to use": "Not specified; standard legal document.",
      "Remarks": "Commonly includes Certificate of Incorporation, Partnership Deed, Proprietorship Registration, etc."
    },
    {
      "Document Name": "Permanent Account Number (PAN Card)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "For tax compliance and identification of the bidding entity.",
      "Reference Section/Page": "Implied by general GeM tender rules.",
      "Any prescribed format or annexure to use": "Not specified; copy of PAN card.",
      "Remarks": ""
    },
    {
      "Document Name": "Goods and Services Tax (GST) Registration Certificate",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "For tax compliance and financial transactions.",
      "Reference Section/Page": "Implied by general GeM tender rules for any registered business.",
      "Any prescribed format or annexure to use": "Not specified; copy of GST certificate.",
      "Remarks": ""
    },
    {
      "Document Name": "Audited Balance Sheets (for last 3 financial years)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To demonstrate the bidder's minimum average annual financial turnover of 500 Lakhs.",
      "Reference Section/Page": "Page 1: 'Minimum Average Annual Turnover of the bidder (For 3 Years): 500 Lakh (s)'; Page 3: 'Documentary evidence in the form of certified Audited Balance Sheets of relevant periods... shall be uploaded with the bid.'"
    },
    {
      "Document Name": "CA / Cost Accountant Certificate for Turnover (for last 3 financial years)",
      "Mandatory/Optional": "Mandatory (Alternative)",
      "Purpose": "To demonstrate the bidder's minimum average annual financial turnover of 500 Lakhs, as an alternative to audited balance sheets.",
      "Reference Section/Page": "Page 1: 'Minimum Average Annual Turnover of the bidder (For 3 Years): 500 Lakh (s)'; Page 3: '...or a certificate from the Chartered Accountant / Cost Accountant indicating the turnover details for the relevant period shall be uploaded with the bid.'"
    },
    {
      "Document Name": "Earnest Money Deposit (EMD) Instrument / Proof of EMD Submission",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "Bid security for each schedule (Schedule 1: INR 300,000; Schedule 2: INR 200,000; Schedule 3: INR 180,000).",
      "Reference Section/Page": "Page 2: 'EMD Detail' section for schedule-wise amounts; Page 3: '(a). EMD EXEMPTION' for rules.",
      "Any prescribed format or annexure to use": "Bank Guarantee (BG) or other acceptable form as per GeM GTC (e.g., FDR, online payment proof). Beneficiary: Accountant, Lucknow, Food and Civil Supplies Department Uttar Pradesh, UP Government Employees Welfare Corporation, (Accountant).",
      "Remarks": "MSEs (manufacturers for goods and service providers for services) may be exempt if they upload a valid supporting document (e.g., Udyam Certificate). Traders are not exempt from EMD."
    },
    {
      "Document Name": "Price Break Up Sheet (Excel Format)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To provide a detailed financial breakup of the quoted price.",
      "Reference Section/Page": "Page 2: 'Financial Document Indicating Price Breakup Required: Yes'; Page 3: 'Excel Upload Required: Price Break Up Sheet - 1760708067.xlsx'."
    },
    {
      "Document Name": "Copies of Relevant Contracts / Orders (Proof of Past Experience)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To prove 3 years of past experience in providing similar services, specifically demonstrating completion of projects with minimum values (Parikshetr-1: Rs 3 crores; Parikshetr-2: Rs 2 crores; Parikshetr-3: Rs 1.70 crores) during any one of the preceding three financial years.",
      "Reference Section/Page": "Page 1: 'Years of Past Experience Required for same/similar service: 3 Year (s)'; Page 3: 'Copies of relevant contracts / orders to be uploaded along with bid in support of having provided services during each of the Financial year.'; Page 6: 'Buyer Added text based ATC clauses - Experience'."
    },
    {
      "Document Name": "Project Completion Certificates / Work Orders (Specific Experience)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To specifically prove completion of at least two projects matching the value criteria for each Parikshetr as defined in the Buyer Added ATC clauses.",
      "Reference Section/Page": "Page 6: 'Buyer Added text based ATC clauses - Experience': 'completed at least two projects of value not less than Rs 3 crores, Rs 2 crores & Rs 1.70 crores each in case of parikshetr-1, parikshetr-2 & parikshetr-3 respectively during any one of the preceding three financial years.'"
    },
    {
      "Document Name": "Technical Proposal / Methodology (Compliance with 'prescribed quality specified in ATC')",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To demonstrate the bidder's capability to meet the technical specifications for handling, transport, storage, and supply of Rice (common) as per the prescribed quality for each Parikshetr.",
      "Reference Section/Page": "Page 1: 'Item Category' (details the service); Page 4 & 5: 'Technical Specifications' (defines the core service category and implies detailed compliance).",
      "Remarks": "This document should outline the bidder's plan, resources, quality control measures, and logistics for fulfilling the service requirements."
    },
    {
      "Document Name": "Make in India (MII) Compliance Declaration",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To declare compliance with the Make in India policy.",
      "Reference Section/Page": "Page 3: 'MII Compliance: Yes'."
    },
    {
      "Document Name": "Land Border Declaration / Certificate of Registration with Competent Authority (if applicable)",
      "Mandatory/Optional": "Mandatory (Conditional)",
      "Purpose": "To declare compliance with restrictions on procurement from bidders of countries sharing a land border with India.",
      "Reference Section/Page": "Page 7: 'In terms of GeM GTC clause 26 regarding Restrictions on procurement from a bidder of a country which shares a land border with India...'"
    },
    {
      "Document Name": "Self-Declaration of No Blacklisting / Debarment",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To confirm that the bidder has not been blacklisted or debarred by any government authority.",
      "Reference Section/Page": "Implied by general GeM tender rules.",
      "Any prescribed format or annexure to use": "Standard GeM format for such declarations."
    },
    {
      "Document Name": "Power of Attorney / Letter of Authority",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To authorize the signatory to submit the bid and undertake contractual obligations on behalf of the bidding entity.",
      "Reference Section/Page": "Implied by general GeM tender rules.",
      "Any prescribed format or annexure to use": "Standard legal format."
    },
    {
      "Document Name": "Duly Filled and Signed Commercial Bid / Price Quote",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "To submit the financial offer for the services.",
      "Reference Section/Page": "Implied by 'Two Packet Bid' (Page 2) and the 'Price Break Up Sheet' requirement (Page 3).",
      "Remarks": "This is the final offer based on the Excel price breakup."
    },
    {
      "Document Name": "Digital Signature Certificate (DSC)",
      "Mandatory/Optional": "Mandatory",
      "Purpose": "For secure and legally binding electronic submission of the bid.",
      "Reference Section/Page": "Implied by GeM platform requirements for online bidding.",
      "Remarks": "Class 3 DSC for authorized signatory."
    },
    {
      "Document Name": "MSE / Udyam Certificate",
      "Mandatory/Optional": "Mandatory (Conditional)",
      "Purpose": "To avail EMD exemption, if the bidder is an eligible MSE manufacturer or service provider.",
      "Reference Section/Page": "Page 3: '(a). EMD EXEMPTION' section.",
      "Remarks": "If claiming EMD exemption, this document is mandatory. The tender explicitly states 'No' for MSE exemption on experience and turnover criteria on Page 1."
    },
    {
      "Document Name": "DPIIT Startup Recognition Certificate",
      "Mandatory/Optional": "Mandatory (Conditional)",
      "Purpose": "Potentially to avail EMD exemption (if applicable per GeM GTC for startups).",
      "Reference Section/Page": "Page 3: '(a). EMD EXEMPTION' section (implicitly, as part of 'valid supporting document for the relevant category as per GeM GTC').",
      "Remarks": "The tender explicitly states 'No' for Startup exemption on experience and turnover criteria on Page 1. EMD exemption for startups would follow general GeM GTC if not explicitly denied."
    }
  ]
}
